  /* Registered per document, not through jsPDF's global addFonts event.
     That event embeds the face in every PDF the app produces — including
     the invoice, which is not set in Calibri and would carry 15 kB of font
     it never draws with. */
  (typeof window !== 'undefined' ? window : this).addCarlito = function (doc) {
    doc.addFileToVFS('Carlito-Regular.ttf', REGULAR);
    doc.addFont('Carlito-Regular.ttf', 'Carlito', 'normal');
    doc.addFileToVFS('Carlito-Bold.ttf', BOLD);
    doc.addFont('Carlito-Bold.ttf', 'Carlito', 'bold');
  };
